def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
errors=[]; removed=[]; skipped=[]
for src_rel,dst_rel in MOVES.items():
    src=ROOT/src_rel; dst=ROOT/dst_rel
    if not src.exists():
        skipped.append(src_rel); continue
    if not dst.exists():
        errors.append(f"missing archive copy: {dst_rel}"); continue
    if sha(src)!=sha(dst):
        errors.append(f"content mismatch; not deleting: {src_rel}"); continue
    src.unlink(); removed.append(src_rel)
if errors:
    print('PATCH144 stopped with safety errors:')
    print('\n'.join(' - '+x for x in errors))
    sys.exit(1)
print(f'PATCH144 cleanup complete: removed {len(removed)} verified root duplicates; {len(skipped)} already absent.')
